WITH product_totals AS (SELECT product_id, COUNT(DISTINCT quantity) AS unique_products FROM order_items WHERE order_id IN (13, 21, 29) GROUP BY product_id) SELECT products.id, products.category, products.stock_qty, product_totals.unique_products FROM products JOIN product_totals ON products.id = product_totals.product_id WHERE product_totals.unique_products > 6 ORDER BY stock_qty DESC, category
